package com.hbm.machine.reactor.rbmk.irradiation;
import com.google.gson.*;
import com.hbm.fluid.*;
import com.hbm.hazard.HbmHazards;
import com.hbm.machine.alloy.AlloyStackIngredient;
import com.hbm.machine.centrifuge.CentrifugeNbtIngredient;
import com.hbm.material.MaterialDistributionConfig;
import com.hbm.recipe.LegacyOreIngredient;
import com.hbm.recipe.generic.GenericIngredient;
import com.hbm.registry.HbmOreDictionary;
import com.mojang.logging.LogUtils;
import java.nio.file.*;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.nbt.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.world.item.crafting.*;
import net.neoforged.bus.api.EventPriority;
import net.neoforged.fml.loading.FMLPaths;
import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.event.OnDatapackSyncEvent;
import net.neoforged.neoforge.event.server.ServerAboutToStartEvent;
/** One genuine source OutgasserRecipes table shared by RBMK/fusion, including original hbmIrradiation.json replacement grammar. */
public final class RbmkIrradiationRecipes {
    private static final Map<RecipeManager,Map<ResourceLocation,RecipeHolder<?>>> INSTALLED=new WeakHashMap<>();private static final Map<String,String> ALIASES=new HashMap<>();
    private record View(Collection<RecipeHolder<?>> snapshot,List<RbmkIrradiationRecipe> recipes){}private static final Map<RecipeManager,View> VIEWS=new WeakHashMap<>();
    public static void register(){try(var stream=RbmkIrradiationRecipes.class.getResourceAsStream("/hbm/irradiation-item-aliases.json")){if(stream!=null)JsonParser.parseReader(new java.io.InputStreamReader(stream,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject().entrySet().forEach(entry->ALIASES.put(entry.getKey(),entry.getValue().getAsString()));}catch(Exception error){throw new IllegalStateException(error);}NeoForge.EVENT_BUS.addListener((ServerAboutToStartEvent event)->install(event.getServer()));NeoForge.EVENT_BUS.addListener(EventPriority.LOWEST,(OnDatapackSyncEvent event)->{var server=event.getPlayerList().getServer();if(event.getPlayer()==null||!INSTALLED.containsKey(server.getRecipeManager()))install(server);});}
    public static List<RbmkIrradiationRecipe> recipes(RecipeManager manager){var snapshot=manager.getOrderedRecipes();synchronized(VIEWS){var previous=VIEWS.get(manager);if(previous!=null&&previous.snapshot==snapshot)return previous.recipes;var recipes=manager.getAllRecipesFor(RbmkOutgasserContent.RECIPE.get()).stream().map(RecipeHolder::value).sorted(Comparator.comparingInt(RbmkIrradiationRecipe::order)).toList();VIEWS.put(manager,new View(snapshot,recipes));return recipes;}}
    /** Exact ComparableStack lookup precedes original ordered ore-dictionary names; fusionOnly belongs to each real consumer. */
    public static RbmkIrradiationRecipe find(RecipeManager manager,ItemStack input){if(input.isEmpty())return null;var recipes=recipes(manager);for(int i=recipes.size()-1;i>=0;i--){var recipe=recipes.get(i);if(recipe.keyKind().equals("item")&&recipe.input().count()==1&&recipe.input().matches(input,true))return recipe;}for(String tag:HbmOreDictionary.tags(input))for(int i=recipes.size()-1;i>=0;i--){var recipe=recipes.get(i);if(recipe.keyKind().equals("dict")&&recipe.sourceKey().equals(tag)&&recipe.input().count()==1&&recipe.input().matches(input,true))return recipe;}return null;}
    private static void install(MinecraftServer server){var manager=server.getRecipeManager();var previous=INSTALLED.getOrDefault(manager,Map.of());var merged=new LinkedHashMap<ResourceLocation,RecipeHolder<?>>();for(var holder:manager.getOrderedRecipes())if(previous.get(holder.id())!=holder)merged.put(holder.id(),holder);var added=new LinkedHashMap<ResourceLocation,RecipeHolder<?>>();Path directory=FMLPaths.CONFIGDIR.get().resolve("hbmRecipes"),active=directory.resolve("hbmIrradiation.json");try{Files.createDirectories(directory);if(Files.isRegularFile(active)){merged.values().removeIf(holder->holder.value().getType()==RbmkOutgasserContent.RECIPE.get());JsonObject root;try(var reader=Files.newBufferedReader(active)){root=JsonParser.parseReader(reader).getAsJsonObject();}int index=0;for(var value:root.getAsJsonArray("recipes")){try{var recipe=legacy(value.getAsJsonObject(),index);added.values().removeIf(holder->sameKey((RbmkIrradiationRecipe)holder.value(),recipe));var id=ResourceLocation.parse("hbm:irradiation/config/"+index);added.put(id,new RecipeHolder<>(id,recipe));}catch(Exception error){LogUtils.getLogger().warn("Unbound actual irradiation custom row {}",index,error);}index++;}}else template(directory.resolve("_hbmIrradiation.json"),recipes(manager));}catch(Exception error){LogUtils.getLogger().error("Cannot load original irradiation replacement recipes",error);}added.forEach(merged::put);if(!added.isEmpty()||!previous.isEmpty()||Files.isRegularFile(active))manager.replaceRecipes(merged.values());INSTALLED.put(manager,added);}
    private static boolean sameKey(RbmkIrradiationRecipe a,RbmkIrradiationRecipe b){if(!a.keyKind().equals(b.keyKind())||a.input().count()!=b.input().count())return false;if(a.keyKind().equals("dict"))return a.sourceKey().equals(b.sourceKey());var one=a.input().ingredient().getItems();var two=b.input().ingredient().getItems();if(one.length==0||two.length==0||one[0].getItem()!=two[0].getItem())return false;int x=metadata(one[0]),y=metadata(two[0]);return (x==32767||y==32767||x==y)&&(!a.keyKind().equals("nbt")||one[0].getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).equals(two[0].getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY)));}
    private static int metadata(ItemStack stack){return stack.getOrDefault(HbmHazards.LEGACY_METADATA.get(),stack.getDamageValue());}
    private static ItemStack stack(JsonArray values)throws Exception{String source=values.get(0).getAsString();String id=ALIASES.getOrDefault(source,source);int meta=values.size()>2?values.get(2).getAsInt():0;var stack=MaterialDistributionConfig.legacyStack(id,meta);if(stack.isEmpty())throw new IllegalArgumentException("Unregistered actual irradiation item "+source);stack.setCount(values.size()>1?values.get(1).getAsInt():1);if(values.size()>3)stack.set(DataComponents.CUSTOM_DATA,CustomData.of(TagParser.parseTag(values.get(3).getAsString())));return stack;}
    private static RbmkIrradiationRecipe legacy(JsonObject value,int order)throws Exception{var in=value.getAsJsonArray("input");String kind=in.get(0).getAsString(),key;int count=in.size()>2?in.get(2).getAsInt():1,meta=in.size()>3?in.get(3).getAsInt():0;Ingredient ingredient;if(kind.equals("dict")){key=HbmOreDictionary.registerName(in.get(1).getAsString());ingredient=new LegacyOreIngredient(ResourceLocation.parse(key)).toVanilla();}else{var spec=array(in.get(1).getAsString(),1,kind.equals("nbt")?0:meta);var example=stack(spec);key=BuiltInRegistries.ITEM.getKey(example.getItem()).toString();if(kind.equals("nbt")){var nbt=in.size()>4?TagParser.parseTag(in.get(4).getAsString()):new CompoundTag();ingredient=new CentrifugeNbtIngredient(example,nbt).toVanilla();}else ingredient=new AlloyStackIngredient(example).toVanilla();}var solid=value.has("solidOutput")?stack(value.getAsJsonArray("solidOutput")):ItemStack.EMPTY;Optional<FluidStack> gas=Optional.empty();if(value.has("fluidOutput")){var spec=value.getAsJsonArray("fluidOutput");gas=Optional.of(new FluidStack(HbmFluids.fromName(spec.get(0).getAsString()),spec.get(1).getAsInt(),spec.size()>2?spec.get(2).getAsInt():0));}if(solid.isEmpty()&&gas.isEmpty())throw new IllegalArgumentException("Source irradiation has no output");return new RbmkIrradiationRecipe(new GenericIngredient(ingredient,count),solid,gas,value.has("fusionOnly")&&value.get("fusionOnly").getAsBoolean(),kind,key,order);}
    private static JsonArray array(Object...values){var array=new JsonArray();for(var value:values)if(value instanceof Number number)array.add(number);else array.add(value.toString());return array;}
    private static JsonArray jsonStack(ItemStack stack){var values=array(BuiltInRegistries.ITEM.getKey(stack.getItem()).toString(),stack.getCount(),metadata(stack));var custom=stack.get(DataComponents.CUSTOM_DATA);if(custom!=null)values.add(custom.copyTag().toString());return values;}
    private static void template(Path path,List<RbmkIrradiationRecipe> recipes)throws Exception{var root=new JsonObject();var values=new JsonArray();for(var recipe:recipes){var input=recipe.input();JsonArray source;if(recipe.keyKind().equals("dict")){var raw=HbmOreDictionary.allNames().stream().filter(name->("hbm:legacy_ore_dict/"+name.toLowerCase(Locale.ROOT)).equals(recipe.sourceKey())).findFirst().orElse(recipe.sourceKey().replace("hbm:legacy_ore_dict/",""));source=array("dict",raw,input.count());}else{var examples=input.ingredient().getItems();if(examples.length==0)continue;var example=examples[0];source=array(recipe.keyKind(),BuiltInRegistries.ITEM.getKey(example.getItem()).toString(),input.count(),metadata(example));if(recipe.keyKind().equals("nbt"))source.add(example.getOrDefault(DataComponents.CUSTOM_DATA,CustomData.EMPTY).copyTag().toString());}var row=new JsonObject();row.add("input",source);if(!recipe.solid().isEmpty())row.add("solidOutput",jsonStack(recipe.solid()));if(recipe.gas().isPresent()){var fluid=recipe.gas().get();row.add("fluidOutput",array(fluid.type.getName(),fluid.fill,fluid.pressure));}row.addProperty("fusionOnly",recipe.fusionOnly());values.add(row);}root.add("recipes",values);Files.writeString(path,new GsonBuilder().setPrettyPrinting().create().toJson(root)+"\n");}
    private RbmkIrradiationRecipes(){}
}
